text:
```yaml
design:
  schema: fpga-design-agent/project/v1
  name: vga_median_720p
  board: nexys_a7_100t
  clocks:
    - {name: clk_sys, source: board, port: CLK100MHZ, mhz: 100}
    - {name: clk_pix, source: mmcm, from: clk_sys, mhz: 74.25}
  resets:
    - {name: rst_sys, domain: clk_sys, polarity: active_high, style: sync, from: CPU_RESETN, via: reset_sync}
    - {name: rst_pix, domain: clk_pix, polarity: active_high, style: sync, from: rst_sys, via: reset_sync}
  shell: {design_id: VMED, clock: clk_sys, reset: rst_sys}
  modules:
    - {name: video_timing, kind: rtl, clocks: {clk: clk_pix}, resets: {rst: rst_pix}}
    - {name: color_bars, kind: rtl, clocks: {clk: clk_pix}, resets: {rst: rst_pix}}
    - {name: median_filter, kind: rtl, clocks: {clk: clk_pix}, resets: {rst: rst_pix}}
    - {name: frame_counter, kind: rtl, clocks: {clk: clk_pix}, resets: {rst: rst_pix}}
    - {name: video_cdc, kind: rtl, clocks: {clk_sys: clk_sys, clk_pix: clk_pix}, resets: {rst_sys: rst_sys, rst_pix: rst_pix}}
    - {name: video_output, kind: rtl, clocks: {clk: clk_pix}, resets: {rst: rst_pix}}
    - name: video_control
      kind: rtl
      clocks: {clk: clk_sys}
      resets: {rst: rst_sys}
      window_base: 0x80
      register_crossings: {}
  connections: []
  board_ports:
    - {name: CLK100MHZ, dir: in, drive: input, to: clk_sys}
    - {name: CPU_RESETN, dir: in, drive: input, to: rst_sys}
    - {name: UART_TXD_IN, dir: in, drive: input, to: shell.uart_rx}
    - {name: UART_RXD_OUT, dir: out, drive: push-pull, from: shell.uart_tx}
    - {name: BTNC, dir: in, drive: input, to: video_output.btnc}
    - {name: VGA_HS, dir: out, drive: push-pull, from: video_output.hsync}
    - {name: VGA_VS, dir: out, drive: push-pull, from: video_output.vsync}
    - {name: "VGA_R[3:0]", dir: out, drive: push-pull, from: video_output.red}
    - {name: "VGA_G[3:0]", dir: out, drive: push-pull, from: video_output.green}
    - {name: "VGA_B[3:0]", dir: out, drive: push-pull, from: video_output.blue}
    - {name: "LED[0]", dir: out, drive: push-pull, from: clk_pix.locked}
  owned: []
  assumptions:
    - id: A-1
      text: "PAT accepts only pattern number 0; other values return an ASCII error and leave the selected pattern unchanged."
      default: "PAT 0 selects the specified colour bars; unsupported pattern numbers return an error."
      reason: "Only eight colour bars are specified; additional selectable patterns and test-shell pattern selection are not specified."
      affects: [video_control.contract.registers, design.shell]
      status: open
    - id: A-2
      text: "The median-filter output is delayed by 1651 pixel clocks relative to the corresponding input pixel."
      default: "Use one line plus one pixel clock of neighbourhood look-ahead."
      reason: "A 3 x 3 raster neighbourhood needs the next line and next pixel before the centre pixel can be filtered; the specification does not state implementation latency."
      affects: [median_filter.contract.latency]
      status: open
    - id: A-3
      text: "The pixel-clock MMCM is configured for 74.25 MHz from the 100 MHz board oscillator."
      default: "Use an MMCM configuration that generates 74.25 MHz."
      reason: "The required frequency and source are specified, but MMCM implementation details are not."
      affects: [design.clocks.clk_pix]
      status: open
  assumptions_note: "The USB-UART shell is the always-present shell/rtl/fpga_shell.sv. Its register window is 0x80-0xFF; video_control uses offsets 0x00 and 0x04 within that window."

contracts:
  video_timing:
    schema: fpga-design-agent/contract/v1
    module: video_timing
    summary: "Generate 720p60 raster coordinates, active-picture qualification, and positive sync."
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: x, dir: out, width: 11, clock: clk, reset_value: 0}
      - {name: y, dir: out, width: 10, clock: clk, reset_value: 0}
      - {name: active, dir: out, width: 1, clock: clk, reset_value: 0}
      - {name: hsync, dir: out, width: 1, clock: clk, reset_value: 0}
      - {name: vsync, dir: out, width: 1, clock: clk, reset_value: 0}
    data_formats:
      - {name: x_coord, format: u11, packing: "Horizontal pixel coordinate"}
      - {name: y_coord, format: u10, packing: "Vertical line coordinate"}
    latency:
      - {from: clk, to: x, cycles: 0}
      - {from: clk, to: y, cycles: 0}
    throughput:
      - {interface: raster, beats_per_cycle: 1}

  color_bars:
    schema: fpga-design-agent/contract/v1
    module: color_bars
    summary: "Generate the specified default vertical colour-bar test picture."
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: x, dir: in, width: 11, clock: clk}
      - {name: y, dir: in, width: 10, clock: clk}
      - {name: active, dir: in, width: 1, clock: clk}
      - {name: pattern, dir: in, width: 2, clock: clk, reset_value: 0}
      - {name: red, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: green, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: blue, dir: out, width: 4, clock: clk, reset_value: 0}
    data_formats:
      - {name: channel, format: u4, packing: "One VGA colour channel"}
    latency:
      - {from: x, to: red, cycles: 0}
      - {from: y, to: blue, cycles: 0}
    throughput:
      - {interface: pixels, beats_per_cycle: 1}

  median_filter:
    schema: fpga-design-agent/contract/v1
    module: median_filter
    summary: "Compute each output channel's median over a 3 x 3 pixel neighbourhood and delay timing qualifiers to match."
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: in_red, dir: in, width: 4, clock: clk}
      - {name: in_green, dir: in, width: 4, clock: clk}
      - {name: in_blue, dir: in, width: 4, clock: clk}
      - {name: in_active, dir: in, width: 1, clock: clk}
      - {name: in_hsync, dir: in, width: 1, clock: clk}
      - {name: in_vsync, dir: in, width: 1, clock: clk}
      - {name: out_red, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: out_green, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: out_blue, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: out_active, dir: out, width: 1, clock: clk, reset_value: 0}
      - {name: out_hsync, dir: out, width: 1, clock: clk, reset_value: 0}
      - {name: out_vsync, dir: out, width: 1, clock: clk, reset_value: 0}
    data_formats:
      - {name: channel, format: u4, packing: "One VGA colour channel"}
    latency:
      - {from: in_red, to: out_red, cycles: 1651}
      - {from: in_green, to: out_green, cycles: 1651}
      - {from: in_blue, to: out_blue, cycles: 1651}
      - {from: in_hsync, to: out_hsync, cycles: 1651}
      - {from: in_vsync, to: out_vsync, cycles: 1651}
    throughput:
      - {interface: pixels, beats_per_cycle: 1}

  frame_counter:
    schema: fpga-design-agent/contract/v1
    module: frame_counter
    summary: "Maintain a 32-bit unsigned frame count, incrementing once at each frame end."
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: frame_end, dir: in, width: 1, clock: clk}
      - {name: count, dir: out, width: 32, clock: clk, reset_value: 0}
    data_formats:
      - {name: frame_count, format: u32, packing: "Unsigned video frame count"}
    latency:
      - {from: frame_end, to: count, cycles: 1}
    throughput:
      - {interface: count, beats_per_cycle: 1}

  video_cdc:
    schema: fpga-design-agent/contract/v1
    module: video_cdc
    summary: "Cross pattern selection from the shell clock to the pixel clock and frame count in the reverse direction."
    clocks:
      - {name: clk_sys, port: clk_sys, max_mhz: 100}
      - {name: clk_pix, port: clk_pix, max_mhz: 74.25}
    resets:
      - {name: rst_sys, port: rst_sys, clock: clk_sys, polarity: active_high, style: sync}
      - {name: rst_pix, port: rst_pix, clock: clk_pix, polarity: active_high, style: sync}
    ports:
      - {name: clk_sys, dir: in}
      - {name: clk_pix, dir: in}
      - {name: rst_sys, dir: in}
      - {name: rst_pix, dir: in}
      - {name: pattern_sys, dir: in, width: 2, clock: clk_sys}
      - {name: frame_count_pix, dir: in, width: 32, clock: clk_pix}
      - {name: pattern_pix, dir: out, width: 2, clock: clk_pix, reset_value: 0}
      - {name: frame_count_sys, dir: out, width: 32, clock: clk_sys, reset_value: 0}
    data_formats:
      - {name: pattern_number, format: u2, packing: "Pattern selection number"}
      - {name: frame_count, format: u32, packing: "Unsigned video frame count"}

  video_control:
    schema: fpga-design-agent/contract/v1
    module: video_control
    summary: "Expose pattern selection and frame count in the shell register window."
    clocks:
      - {name: clk, port: clk, max_mhz: 100}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: pattern, dir: out, width: 2, clock: clk, reset_value: 0}
      - {name: frame_count_in, dir: in, width: 32, clock: clk}
      - {name: frame_count, dir: out, width: 32, clock: clk, reset_value: 0}
    data_formats:
      - {name: pattern_number, format: u2, packing: "Pattern selection number"}
      - {name: frame_count, format: u32, packing: "Unsigned video frame count"}
    registers:
      bus: top
      map:
        - name: PATTERN
          offset: 0x00
          access: RW
          reset: 0
          width: 2
          volatile: false
          fields: [{name: pattern, bits: [1, 0], port: pattern}]
        - name: FRAME_COUNT
          offset: 0x04
          access: RO
          reset: 0
          width: 32
          volatile: true
          fields: [{name: count, bits: [31, 0], port: frame_count}]
    latency:
      - {from: pattern, to: pattern, cycles: 0}
      - {from: frame_count_in, to: frame_count, cycles: 0}

  video_output:
    schema: fpga-design-agent/contract/v1
    module: video_output
    summary: "Drive VGA sync and colour pins; blank colour for inactive video, BTNC, or an unlocked pixel clock."
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: btnc, dir: in, width: 1, clock: async}
      - {name: locked, dir: in, width: 1, clock: clk}
      - {name: active, dir: in, width: 1, clock: clk}
      - {name: in_hsync, dir: in, width: 1, clock: clk}
      - {name: in_vsync, dir: in, width: 1, clock: clk}
      - {name: in_red, dir: in, width: 4, clock: clk}
      - {name: in_green, dir: in, width: 4, clock: clk}
      - {name: in_blue, dir: in, width: 4, clock: clk}
      - {name: hsync, dir: out, width: 1, clock: clk, reset_value: 0}
      - {name: vsync, dir: out, width: 1, clock: clk, reset_value: 0}
      - {name: red, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: green, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: blue, dir: out, width: 4, clock: clk, reset_value: 0}
    data_formats:
      - {name: channel, format: u4, packing: "One VGA colour channel"}
    latency:
      - {from: in_hsync, to: hsync, cycles: 0}
      - {from: in_red, to: red, cycles: 0}

module_specs:
  video_timing: |
    Count 1650 pixel clocks per line and 750 lines per frame. The active region is
    1280 by 720 pixels; use front porch/sync/back porch values of 110/40/220
    horizontal clocks and 5/5/20 vertical lines. Generate positive syncs and a
    frame_end pulse once per frame. The pixel clock is 74.25 MHz.
  color_bars: |
    For active x coordinates, generate eight 160-pixel-wide vertical bars ordered
    white, yellow, cyan, green, magenta, red, blue, black. PAT 0 selects this
    pattern. No alternative patterns are defined; handling other PAT values is
    covered by assumption A-1.
  median_filter: |
    Compute the median independently for red, green, and blue over each 3 x 3
    neighbourhood. Replicate the nearest active-picture pixel at picture boundaries.
    Delay active and sync qualifiers with the filtered picture. The proposed
    fixed delay is 1651 pixel clocks, as recorded in assumption A-2.
  frame_counter: |
    Reset to zero and increment the unsigned 32-bit counter once on each frame_end.
  video_cdc: |
    Synchronize the pattern selection from clk_sys to clk_pix. Transfer the frame
    count from clk_pix to clk_sys using a CDC scheme appropriate for a changing
    multi-bit counter, such as Gray-code synchronization.
  video_control: |
    Implement PATTERN as a read/write register at shell-window offset 0x00 and
    FRAME_COUNT as a read-only register at offset 0x04. The shell owns the USB-UART
    and register window; support newline-terminated ASCII ID?, PAT n, and FRAME?
    commands with line-terminated responses. PAT command behavior beyond the
    specified bars is proposed in assumption A-1.
  video_output: |
    Forward delayed syncs. Drive red, green, and blue to zero outside active video,
    while BTNC is pressed, or while the pixel clock is not locked. Otherwise forward
    the filtered colour channels.

requirements:
  - id: S-1
    text: "Generate 1280 x 720, 60 Hz video timing with a 74.25 MHz pixel clock, 1650 pixel clocks per line (1280 active, 110 front porch, 40 sync, 220 back porch), 750 lines per frame (720 active, 5 front porch, 5 sync, 20 back porch), and positive horizontal and vertical sync."
    proof: [simulation, hardware, analysis]
    modules: [video_timing, top]
  - id: S-2
    text: "By default, generate eight vertical colour bars, each 160 active pixels wide, in this order: white, yellow, cyan, green, magenta, red, blue, black."
    proof: [simulation, hardware]
    modules: [color_bars, video_control, top]
  - id: S-3
    text: "For each output pixel, compute the median independently for each colour channel over the pixel's 3 x 3 neighbourhood."
    proof: [simulation, formal]
    modules: [median_filter, top]
  - id: S-4
    text: "Keep the output picture and sync signals aligned to the video timing that would be produced without the median filter."
    proof: [simulation, hardware]
    modules: [median_filter, video_output, top]
  - id: S-5
    text: "Drive all colour outputs to zero outside the active picture, while BTNC is pressed, or while the pixel clock is not stable."
    proof: [simulation, hardware]
    modules: [video_output, top]
  - id: S-6
    text: "Light LED[0] when the pixel clock is stable."
    proof: [hardware]
    modules: [top]
  - id: S-7
    text: "Provide a USB-UART test shell at 115200 baud with design ID VMED that allows a host to choose the pattern and read a frame counter."
    proof: [simulation, hardware]
    modules: [video_control, top]

